#include <bits/stdc++.h>
using namespace std;
typedef signed long long ll;
#define FOR(i, n) for (int i = 0; i < (n); ++i)
static ll MOD;
struct Mod {
    ll x;
    Mod(ll val = 0) { if (MOD && (val >= MOD || val < 0)) val = (val % MOD + MOD) % MOD; x = val; }
    static Mod pow(Mod a, ll e = MOD - 2) {
        ll b = a.x, r = 1;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return Mod(r);
    }
    Mod& operator+=(Mod o) { x += o.x; if (x >= MOD) x -= MOD; return *this; }
    Mod& operator-=(Mod o) { x += MOD - o.x; if (x >= MOD) x -= MOD; return *this; }
    Mod& operator*=(Mod o) { x = x * o.x % MOD; return *this; }
    Mod& operator/=(Mod o) { assert(o.x); *this *= pow(o); return *this; }
    Mod operator+(Mod o) const { Mod r(*this); return r += o; }
    Mod operator-(Mod o) const { Mod r(*this); return r -= o; }
    Mod operator*(Mod o) const { Mod r(*this); return r *= o; }
    Mod operator/(Mod o) const { Mod r(*this); return r /= o; }
    friend ostream& operator<<(ostream& os, Mod a) { os << a.x; return os; }
};
int N, M;
Mod f1[505], f2[505], g1[505][505], g2[505][505];
ll combi(ll n, ll k) {
    static ll fac[400002], inv[400002], fiv[400002];
    if (fac[0] == 0) {
        inv[1] = fac[0] = fiv[0] = 1;
        for (int i = 2; i <= 400001; ++i) inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD;
        for (int i = 1; i <= 400001; ++i) {
            fac[i] = fac[i-1] * i % MOD;
            fiv[i] = fiv[i-1] * inv[i] % MOD;
        }
    }
    if (k < 0 || k > n) return 0;
    return fiv[k] * fac[n] % MOD * fiv[n-k] % MOD;
}
void solve() {
    cin >> N >> M >> MOD;
    f1[0] = 1;
    // first compute all f1
    for (int i = 1; i <= N; ++i)
        for (int j = 1; j <= i; ++j)
            f1[i] += Mod(i+1) * f1[j-1] * f1[i-j] * combi(i-1, j-1);
    // then compute f2
    for (int i = 1; i <= N; ++i)
        for (int j = 1; j <= i; ++j) {
            f2[i] += Mod(i+1) * (f2[i-j] * f1[j-1] + f1[i-j] * f2[j-1]) * combi(i-1, j-1);
            f2[i] += f1[j-1] * f1[i-j] * combi(i-1, j-1) * (combi(j, 2) + combi(i-j+1, 2));
        }
    g1[0][0] = 1;
    for (int i = 1; i <= N; ++i) {
        for (int j = 0; j < i; ++j) {
            g1[i][j] = g1[i-1][j];
            g2[i][j] = g2[i-1][j];
            for (int l = 1; l <= j; ++l) {
                g1[i][j] += f1[l] * g1[i-l-1][j-l] * combi(j, l);
                g2[i][j] += (f1[l] * g2[i-l-1][j-l] + f2[l] * g1[i-l-1][j-l]) * combi(j, l);
            }
        }
        g1[i][i] = f1[i];
        g2[i][i] = f2[i];
    }
    cout << g2[N][M] << '\n';
}
int main(int argc, char** argv) {
    if (argc == 1) ios::sync_with_stdio(false), cin.tie(0);
    else {
        string s;
        for (int i = 1; i < argc; ++i) s += argv[i], s += '\n';
        for (int i = (int)s.size()-1; i >= 0; --i) ungetc(s[i], stdin);
    }
    cout.tie(0);
    solve();
    return 0;
}
